/**
 * @brief 查询当前状态
 */
static void BT_HandleQueryStatus(void)
{
    char buffer[128];

    sprintf(buffer, "MODE:%s,SPD:%d,BASE:%d,VAC:%s,VS:%d,KEY:%s,ESTOP:%s\r\n",
            (g_motion_mode == MOTION_IDLE) ? "IDLE" :
