static void BT_HandleKeyControlMode(uint8_t enabled)
{
    g_key_control_mode = (enabled > 0) ? 1 : 0;

    if(g_key_control_mode)
    {
        // 进入键控模式，清除急停，停止当前运动
        g_emergency_stop = 0;
        g_motion_mode = MOTION_IDLE;
        g_motion_speed = 0;

        // 同步全局模式变量
