        star_car = 0;  // 退出巡线模式

        // 设置LED为蓝色表示键控模式
        RGB_SetColor(RGB_COLOR_B);

        BT_SendResponse("OK:KEY=ON\r\n");
    }
    else
    {
        // 退出键控模式，停止运动
        g_motion_mode = MOTION_IDLE;
        g_motion_speed = 0;

        // 同步全局模式变量
        g_bt_key_control_mode = 0;

