/**
 * @brief 解析并执行字符串命令
 * @param cmd: 命令字符串（不含换行符）
 */
static void BT_ParseCommand(const char *cmd)
{
    // 去掉可能的空格
    while(*cmd == ' ') cmd++;

    // 检查空命令
    if(strlen(cmd) == 0) return;

    // 解析参数（如果有的话）
    int param = 0;
    char cmd_part[16] = {0};
    const char *colon = strchr(cmd, ':');

    if(colon != NULL)
    {
        // 有参数的命令
        int cmd_len = colon - cmd;
        if(cmd_len > 15) cmd_len = 15;
        strncpy(cmd_part, cmd, cmd_len);
        cmd_part[cmd_len] = 0;
        param = atoi(colon + 1);
    }
    else
    {
        // 无参数的命令
        strncpy(cmd_part, cmd, 15);
    }

    // 转换为大写方便比较
    for(int i = 0; cmd_part[i]; i++)
    {
        if(cmd_part[i] >= 'a' && cmd_part[i] <= 'z')
        {
            cmd_part[i] -= 32;
        }
    }

    // ========== 全局命令（任何时候都生效） ==========

    // 急停命令 - 最高优先级
    if(strcmp(cmd_part, "ESTOP") == 0 || strcmp(cmd_part, "E") == 0)
    {
        BT_EmergencyStop();
        return;
    }

    // 清除急停
    if(strcmp(cmd_part, "CLR") == 0 || strcmp(cmd_part, "CLEAR") == 0)
    {
        BT_ClearEmergencyStop();
        return;
    }

    // 负压开
    if(strcmp(cmd_part, "VON") == 0)
    {
        BT_VacuumControl(1);
        return;
    }

    // 负压关
    if(strcmp(cmd_part, "VOFF") == 0)
    {
        BT_VacuumControl(0);
        return;
    }

    // 负压转速
    if(strcmp(cmd_part, "VS") == 0)
    {
        BT_VacuumSetSpeed((uint8_t)param);
        return;
    }

    // 基础速度设置
    if(strcmp(cmd_part, "SPD") == 0)
    {
        BT_HandleSetBaseSpeed((uint8_t)param);
        return;
    }

    // PID参数设置：PID:kp,ki,kd[,kf]
    if(strcmp(cmd_part, "PID") == 0)
    {
        float kp = 0.0f, ki = 0.0f, kd = 0.0f, kf = 0.0f;
        int args = 0;
        if(colon)
        {
             args = sscanf(colon + 1, "%f,%f,%f,%f", &kp, &ki, &kd, &kf);
        }

        if(args == 3)
        {
            SpeedPID_SetParamBoth(kp, ki, kd);
            SpeedPID_ResetState();
            char buf[48];
            sprintf(buf, "OK:PID=%.2f,%.2f,%.2f\r\n", kp, ki, kd);
            BT_SendResponse(buf);
        }
        else if(args == 4)
        {
            SpeedPID_SetParamBoth(kp, ki, kd);
            SpeedPID_SetFeedForwardBoth(kf);
            SpeedPID_ResetState();
            char buf[64];
            sprintf(buf, "OK:PID=%.2f,%.2f,%.2f,KF=%.2f\r\n", kp, ki, kd, kf);
            BT_SendResponse(buf);
        }
        else
        {
            BT_SendResponse("ERR:PID_FMT\r\n");
        }
        return;
    }

    // 位置环PPID参数设置：PPID:kp,ki,kd,gyro_kd
    if(strcmp(cmd_part, "PPID") == 0)
    {
        float kp = 0.0f, ki = 0.0f, kd = 0.0f, gyro_kd = 0.0f;
        int args = 0;
        if(colon)
        {
             args = sscanf(colon + 1, "%f,%f,%f,%f", &kp, &ki, &kd, &gyro_kd);
        }

        if(args == 4)
        {
            PositionPID_SetGlobalParams(kp, ki, kd, gyro_kd);
            char buf[64];
            sprintf(buf, "OK:PPID=%.1f,%.1f,%.1f,%.1f\r\n", kp, ki, kd, gyro_kd);
            BT_SendResponse(buf);
        }
        else
        {
            BT_SendResponse("ERR:PPID_FMT\r\n");
        }
        return;
    }

    // 单独设置 KF
    if(strcmp(cmd_part, "KF") == 0)
    {
        float kf = 0.0f;
        if(colon && (sscanf(colon + 1, "%f", &kf) == 1))
        {
            SpeedPID_SetFeedForwardBoth(kf);
            char buf[32];
            sprintf(buf, "OK:KF=%.2f\r\n", kf);
            BT_SendResponse(buf);
        }
        else
        {
             BT_SendResponse("ERR:KF_FMT\r\n");
        }
        return;
    }

    // 陀螺仪阻尼开关: GYRO:1=开启, GYRO:0=关闭（架空测试时禁用）
    if(strcmp(cmd_part, "GYRO") == 0)
    {
        PID_GyroDamping_Enable((uint8_t)param);
        char buf[32];
        sprintf(buf, "OK:GYRO=%s\r\n", PID_GyroDamping_IsEnabled() ? "ON" : "OFF");
        BT_SendResponse(buf);
        return;
    }

    // 模拟黑点测试命令: BLK:1,2,3 表示1,2,3路检测到黑线
    // BLK:OFF 关闭模拟模式
    if(strcmp(cmd_part, "BLK") == 0)
    {
        if(colon)
        {
            const char *params = colon + 1;

            // 检查是否关闭模拟模式
            if(strcmp(params, "OFF") == 0 || strcmp(params, "off") == 0 || strcmp(params, "0") == 0)
            {
                BlackPoint_Finder_SetSimulateMode(0);
                BT_SendResponse("OK:BLK=OFF\r\n");
            }
            else
            {
                // 解析通道号列表: 1,2,3 或 9,10
                uint8_t channels[16];
                uint8_t count = 0;
                char buf_parse[64];
                char *token;

                // 复制字符串以避免修改原始数据
                strncpy(buf_parse, params, sizeof(buf_parse) - 1);
                buf_parse[sizeof(buf_parse) - 1] = '\0';

                // 使用逗号分割
                token = strtok(buf_parse, ",");
                while(token != NULL && count < 16)
                {
                    int ch = atoi(token);
                    if(ch >= 0 && ch < 16)
                    {
                        channels[count++] = (uint8_t)ch;
                    }
                    token = strtok(NULL, ",");
                }

                if(count > 0)
                {
                    BlackPoint_Finder_SetSimulateChannels(channels, count);
                    BlackPoint_Finder_SetSimulateMode(1);

                    char resp[64];
                    sprintf(resp, "OK:BLK=%d ch\r\n", count);
                    BT_SendResponse(resp);
                }
                else
                {
                    BT_SendResponse("ERR:BLK_FMT\r\n");
                }
            }
        }
        else
        {
            // 无参数，启用默认模拟模式（中间两路7,8）
            BlackPoint_Finder_SetSimulateMode(1);
            BT_SendResponse("OK:BLK=7,8(default)\r\n");
        }
        return;
    }

    // 状态查询
    if(strcmp(cmd_part, "?STATUS") == 0 || strcmp(cmd_part, "STATUS") == 0 || strcmp(cmd_part, "?") == 0)
    {
        BT_HandleQueryStatus();
        return;
    }

    // ADC查询: ?ADC - 返回16路光电管ADC值和黑线检测情况
    if(strcmp(cmd_part, "?ADC") == 0 || strcmp(cmd_part, "ADC") == 0)
    {
        uint8_t black_flags[SENSOR_COUNT];
        char buf[256];
        int i;

        // 获取黑线检测状态
        BlackPoint_Finder_GetBlackFlags_Dynamic(g_mux_adc_values, black_flags);

        // 发送ADC值 (分两行发送避免缓冲区溢出)
        sprintf(buf, "ADC[0-7]:");
        for(i = 0; i < 8; i++)
        {
            char tmp[16];
            sprintf(tmp, "%d%c", g_mux_adc_values[i], (i < 7) ? ',' : '\n');
            strcat(buf, tmp);
        }
        BT_SendResponse(buf);

        sprintf(buf, "ADC[8-15]:");
        for(i = 8; i < 16; i++)
        {
            char tmp[16];
            sprintf(tmp, "%d%c", g_mux_adc_values[i], (i < 15) ? ',' : '\n');
            strcat(buf, tmp);
        }
        BT_SendResponse(buf);

        // 发送黑线检测状态 (1=黑, 0=白)
        sprintf(buf, "BLK:");
        for(i = 0; i < 16; i++)
        {
            char tmp[4];
            sprintf(tmp, "%d", black_flags[i]);
            strcat(buf, tmp);
        }
        strcat(buf, "\r\n");
        BT_SendResponse(buf);
        return;
    }

    // PID运行状态查询: ?PID - 返回左右轮目标速度、实际速度、PWM输出
    if(strcmp(cmd_part, "?PID") == 0)
    {
        float tgt_l, tgt_r, pwm_l, pwm_r;
        int16_t act_l, act_r;
        char buf[128];

        PID_GetRunStatus(&tgt_l, &tgt_r, &act_l, &act_r, &pwm_l, &pwm_r);

        sprintf(buf, "TGT:L=%.1f,R=%.1f\r\n", tgt_l, tgt_r);
        BT_SendResponse(buf);
        sprintf(buf, "ACT:L=%d,R=%d\r\n", act_l, act_r);
        BT_SendResponse(buf);
        sprintf(buf, "PWM:L=%.0f,R=%.0f\r\n", pwm_l, pwm_r);
        BT_SendResponse(buf);
        return;
    }

    // 里程计状态查询: ?ODOM 或 ODOM - 返回位置、坐标、航向角
    if(strcmp(cmd_part, "?ODOM") == 0 || strcmp(cmd_part, "ODOM") == 0)
    {
        char buf[128];
        Odometer_Data_t odom;
        Odometer_GetData(&odom);

        sprintf(buf, "LOC:%.2f mm\r\n", odom.location);
        BT_SendResponse(buf);
        sprintf(buf, "POS:X=%.2f,Y=%.2f mm\r\n", odom.x, odom.y);
        BT_SendResponse(buf);
        sprintf(buf, "HDG:%.2f deg\r\n", odom.theta);
        BT_SendResponse(buf);
        sprintf(buf, "ENC:L=%ld,R=%ld\r\n", left_ecoder_cnt, right_ecoder_cnt);
        BT_SendResponse(buf);
        return;
    }

    // 快速查询累计里程: ?DIST 或 DIST - 仅返回累计行驶距离
    if(strcmp(cmd_part, "?DIST") == 0 || strcmp(cmd_part, "DIST") == 0)
    {
        char buf[64];
        sprintf(buf, "DIST:%.1f mm\r\n", Odometer_GetLocation());
        BT_SendResponse(buf);
        return;
    }

    // 里程计重置: ODOM_RST - 重置坐标和里程
    if(strcmp(cmd_part, "ODOM_RST") == 0)
    {
        Odometer_Reset();
        BT_SendResponse("OK:ODOM_RST\r\n");
        return;
    }

    // 里程计坐标重置(保留里程): ODOM_ZERO - 仅重置坐标，保留累计里程
    if(strcmp(cmd_part, "ODOM_ZERO") == 0)
    {
        Odometer_ResetCoordinate();
        BT_SendResponse("OK:ODOM_ZERO\r\n");
        return;
    }

    // 编码器校准开始: CALIB_START - 开始记录脉冲数
    if(strcmp(cmd_part, "CALIB_START") == 0 || strcmp(cmd_part, "CALIB") == 0)
    {
        Odometer_StartCalibration();
        RGB_SetColor(RGB_COLOR_YELLOW);
        BT_SendResponse("OK:CALIB_START\r\n");
        BT_SendResponse("Push car straight, then send CALIB_END:distance_mm\r\n");
        return;
    }

    // 编码器校准结束: CALIB_END:1000 - 传入实际推动的距离(mm)
    if(strcmp(cmd_part, "CALIB_END") == 0)
    {
        RGB_SetColor(RGB_COLOR_OFF);

        if(!Odometer_IsCalibrating())
        {
            BT_SendResponse("ERR:NOT_CALIB\r\n");
            return;
        }

        int32_t pulses = Odometer_GetCalibrationPulseCount();

        if(colon && param > 0)
        {
            // 用户指定了实际距离
            float new_pulse_per_mm = Odometer_EndCalibration((float)param);
            char buf[128];
            sprintf(buf, "CALIB:pulses=%ld,dist=%d mm\r\n", pulses, param);
            BT_SendResponse(buf);
            sprintf(buf, "NEW_PULSE_PER_MM=%.4f\r\n", new_pulse_per_mm);
            BT_SendResponse(buf);
            BT_SendResponse("Update ODOM_ENCODER_PULSE_PER_MM in Odometer.h\r\n");
        }
        else
        {
            // 未指定距离，仅显示脉冲数
            char buf[128];
            sprintf(buf, "CALIB:pulses=%ld\r\n", pulses);
            BT_SendResponse(buf);
            sprintf(buf, "If 500mm: %.4f pulse/mm\r\n", (float)pulses / 500.0f);
            BT_SendResponse(buf);
            sprintf(buf, "If 1000mm: %.4f pulse/mm\r\n", (float)pulses / 1000.0f);
            BT_SendResponse(buf);
            BT_SendResponse("Send CALIB_END:xxx (xxx=actual mm)\r\n");
        }
        return;
    }

    // 校准状态查询: ?CALIB - 查看当前校准脉冲数
    if(strcmp(cmd_part, "?CALIB") == 0)
    {
        if(Odometer_IsCalibrating())
        {
            int32_t pulses = Odometer_GetCalibrationPulseCount();
            char buf[64];
            sprintf(buf, "CALIB:pulses=%ld (active)\r\n", pulses);
            BT_SendResponse(buf);
        }
        else
        {
            BT_SendResponse("CALIB:inactive\r\n");
        }
        return;
    }

    // 巡线速度参数设置: ISPD:base,min[,omega_max]
    if(strcmp(cmd_part, "ISPD") == 0)
    {
        float base = 0.0f, spd_min = 0.0f, omega_max = 0.0f;
        int args = 0;

        if(colon)
        {
            args = sscanf(colon + 1, "%f,%f,%f", &base, &spd_min, &omega_max);
        }

        if(args >= 2)
        {
            PID_SetLineSpeedParams(base, spd_min);
            if(args >= 3)
                PID_SetLineSpeedRateK(omega_max);
            char buf[64];
            sprintf(buf, "OK:ISPD=%.0f,%.0f,W=%.1f\r\n", base, spd_min, PID_GetLineSpeedRateK());
            BT_SendResponse(buf);
        }
        else if(args == 0 || colon == NULL)
        {
            float cur_base, cur_min, gw, dw;
            PID_GetLineSpeedParams(&cur_base, &cur_min);
            PID_GetSpeedWeights(&gw, &dw);
            char buf[80];
            sprintf(buf, "ISPD:%.0f,%.0f,W=%.1f,GW=%.1f,DW=%.1f\r\n", 
                    cur_base, cur_min, PID_GetLineSpeedRateK(), gw, dw);
            BT_SendResponse(buf);
        }
        else
        {
            BT_SendResponse("ERR:ISPD_FMT (use ISPD:base,min[,omega_max])\r\n");
        }
        return;
    }

    // 减速权重设置: ISPDW:gyro_w,dev_w
    if(strcmp(cmd_part, "ISPDW") == 0)
    {
        float gw = 0.0f, dw = 0.0f;
        int args = 0;

        if(colon)
        {
            args = sscanf(colon + 1, "%f,%f", &gw, &dw);
        }

        if(args == 2)
        {
            PID_SetSpeedWeights(gw, dw);
            char buf[48];
            sprintf(buf, "OK:ISPDW=%.2f,%.2f\r\n", gw, dw);
            BT_SendResponse(buf);
        }
        else
        {
            PID_GetSpeedWeights(&gw, &dw);
            char buf[48];
            sprintf(buf, "ISPDW:%.2f,%.2f\r\n", gw, dw);
            BT_SendResponse(buf);
        }
        return;
    }

    // 实时数据打印开关（LIVE 命令，每次接收均切换状态）
    if(strcmp(cmd_part, "LIVE") == 0)
    {
        g_live_debug = !g_live_debug;
        if(g_live_debug)
        {
            g_live_debug_last_ms = g_systick_ms;
            BT_SendResponse("OK:LIVE=ON\r\n");
        }
        else
        {
            BT_SendResponse("OK:LIVE=OFF\r\n");
        }
        return;
    }

    // 光电管调试打印开关（SDBG 命令，每次接收均切换状态）
    // 打印格式: "000000011000000\r\n" (16位, 1=黑线, 0=白)
    if(strcmp(cmd_part, "SDBG") == 0)
    {
        g_sensor_debug = !g_sensor_debug;
        if(g_sensor_debug)
        {
            g_sensor_debug_last_ms = g_systick_ms;
            BT_SendResponse("OK:SDBG=ON\r\n");
        }
        else
        {
            BT_SendResponse("OK:SDBG=OFF\r\n");
        }
        return;
    }

    // 键控模式开关
    if(strcmp(cmd_part, "KEY") == 0)
    {
        BT_HandleKeyControlMode((uint8_t)param);
        return;
    }

    // ========== 键控模式命令（需要在键控模式下） ==========

    // 前进
    if(strcmp(cmd_part, "FWD") == 0 || strcmp(cmd_part, "W") == 0)
    {
        BT_HandleMoveForward((uint8_t)param);
        return;
    }

    // 后退
    if(strcmp(cmd_part, "BWD") == 0 || strcmp(cmd_part, "S") == 0)
    {
        BT_HandleMoveBackward((uint8_t)param);
        return;
    }

    // 左转
    if(strcmp(cmd_part, "TL") == 0 || strcmp(cmd_part, "A") == 0)
    {
        BT_HandleTurnLeft((uint8_t)param);
        return;
    }

    // 右转
    if(strcmp(cmd_part, "TR") == 0 || strcmp(cmd_part, "D") == 0)
    {
        BT_HandleTurnRight((uint8_t)param);
        return;
    }

    // 停止移动
    if(strcmp(cmd_part, "STOP") == 0 || strcmp(cmd_part, "X") == 0)
    {
        BT_HandleStop();
        return;
    }

    // 帮助命令
    if(strcmp(cmd_part, "HELP") == 0 || strcmp(cmd_part, "H") == 0)
    {
        BT_SendResponse("=== BT Commands ===\r\n");
        BT_SendResponse("Global: ESTOP,CLR,VON,VOFF,VS:xx,SPD:xx,?\r\n");
        BT_SendResponse("KeyCtrl: FWD,BWD,TL,TR,STOP (or W,S,A,D,X)\r\n");
        BT_SendResponse("KEY:1=Enter KeyMode, KEY:0=Exit\r\n");
        return;
    }

    // 未知命令
    BT_SendResponse("ERR:UNKNOWN_CMD\r\n");
}

/**
 * @brief 处理接收的数据（字符串解析）
 *        非阻塞方式，处理缓冲区内所有已收到的数据
 */
void BT_Process(void)
{
    uint8_t valid = 0;
    int available = Uart2_BytesAvailable();

    // 处理缓冲区中所有可用数据，不再限制32字节
    // 这避免了缓冲区来不及消费而溢出丢字节的问题
    while(available > 0)
    {
        uint8_t byte = Uart2_ReadByte(&valid);
        if(!valid)
        {
            break; // 没有数据了，退出
        }
        available--;

        // 检测换行符，表示命令结束
        if(byte == '\n' || byte == '\r')
        {
            if(g_cmd_overflow)
            {
                // 之前命令溢出，丢弃这条不完整命令，恢复正常
                g_cmd_overflow = 0;
                g_cmd_index = 0;
            }
            else if(g_cmd_index > 0)
            {
                g_cmd_buffer[g_cmd_index] = '\0';
                BT_ParseCommand(g_cmd_buffer);
                g_cmd_index = 0;
            }
        }
        else if(byte >= 32 && byte < 127)  // 可打印字符
        {
            if(g_cmd_index < BT_CMD_BUFFER_SIZE - 1)
            {
                g_cmd_buffer[g_cmd_index++] = (char)byte;
            }
            else
            {
                // 缓冲区满，标记溢出，等待当前命令的换行符后丢弃
                g_cmd_overflow = 1;
                g_cmd_index = 0;
            }
        }
        // 忽略其他控制字符
    }

    /* 实时调试数据周期打印 */
    if(g_live_debug)
    {
        uint32_t now = g_systick_ms;
        if((now - g_live_debug_last_ms) >= LIVE_DEBUG_INTERVAL_MS)
        {
            g_live_debug_last_ms = now;
            float pos_err = (float)position_get / 10.0f - 7.5f;
            float wt = BlackPoint_Finder_GetLastWeightSum();
            char buf[64];
            sprintf(buf, "LIVE:L=%d,R=%d,ERR=%.2f,WT=%.0f\r\n",
                    speed_left, speed_right, pos_err, wt);
            BT_SendResponse(buf);
        }
    }

    /* 光电管调试数据高频打印 */
    if(g_sensor_debug)
    {
        uint32_t now = g_systick_ms;
        if((now - g_sensor_debug_last_ms) >= SENSOR_DEBUG_INTERVAL_MS)
        {
            g_sensor_debug_last_ms = now;
            uint8_t black_flags[SENSOR_COUNT];
            char buf[24];  /* 16 chars + \r\n + \0 */
            uint8_t i;

            BlackPoint_Finder_GetBlackFlags_Dynamic(g_mux_adc_values, black_flags);

            for(i = 0; i < SENSOR_COUNT; i++)
            {
                buf[i] = black_flags[i] ? '1' : '0';
            }
            buf[SENSOR_COUNT] = '\r';
            buf[SENSOR_COUNT + 1] = '\n';
            buf[SENSOR_COUNT + 2] = '\0';
            BT_SendResponse(buf);
        }
    }
}

/**
 * @brief 获取当前运动状态
 */
Motion_Mode_t BT_GetMotionMode(void)
{
    return g_motion_mode;
}

/**
 * @brief 获取当前运动速度
 */
uint8_t BT_GetMotionSpeed(void)
{
    return g_motion_speed;
}

/**
 * @brief 获取完整的蓝牙状态
 */
const BT_State_t* BT_GetState(void)
{
    static BT_State_t state;
    state.motion_mode = g_motion_mode;
    state.motion_speed = g_motion_speed;
    state.base_speed = g_base_speed;
    state.vacuum_enabled = g_vacuum_enabled;
    state.vacuum_speed = g_vacuum_speed;
    state.key_control_mode = g_key_control_mode;
    state.emergency_stop = g_emergency_stop;
    return &state;
}

/**
 * @brief 直接设置吸盘转速（用于硬件K1同步状态）
 */
void BT_SetVacuumSpeedDirect(uint8_t speed_percent)
{
    if(speed_percent > 100) speed_percent = 100;
    g_vacuum_speed = speed_percent;
    g_vacuum_enabled = (speed_percent > 0) ? 1 : 0;
}

/**
 * @brief 获取当前设置的负压风扇转速百分比 (0-100)
 */
uint8_t BT_GetVacuumSpeed(void)
{
    return g_vacuum_speed;
}

/**
 * @brief 发送数据包（保留用于兼容）
 */
void BT_SendPacket(const BT_Packet_t *packet)
{
    // 保留接口，但现在使用字符串方式
    char buf[32];
    sprintf(buf, "PKT:%02X,%02X\r\n", packet->cmd, packet->data);
    BT_SendResponse(buf);
}

#ifndef __BT_COMM_H
#define __BT_COMM_H

#include "stm32f10x.h"
#include <stdint.h>

/*=== 字符串命令协议定义 ===*/
// 命令格式: "CMD:参数\n" 或 "CMD\n"
// 例如: "FWD:50\n" = 前进50%速度, "STOP\n" = 停止

#define BT_CMD_BUFFER_SIZE  64          // 命令缓冲区大小

/*=== 字符串命令定义 ===*/
// 全局命令（任何时候都生效）：
// "ESTOP"    - 急停（立即停止所有电机和负压）
// "VON"      - 负压开
// "VOFF"     - 负压关
// "VS:xx"    - 负压转速 (0-100)
// "SPD:xx"   - 基础速度设置 (0-100)
// "?STATUS"  - 查询状态

// 键控模式命令（需要按下K2进入键控模式）：
// "FWD"      - 前进（使用基础速度）
// "FWD:xx"   - 前进指定速度
// "BWD"      - 后退
// "BWD:xx"   - 后退指定速度
// "TL"       - 左转
// "TL:xx"    - 左转指定速度
// "TR"       - 右转
// "TR:xx"    - 右转指定速度
// "STOP"     - 停止移动

/*=== 数据包结构体（保留用于兼容） ===*/
typedef struct
{
    uint8_t cmd;                        // 命令类型（1字节）
    uint8_t data;                       // 数据（1字节）
} BT_Packet_t;

/*=== 运动模式定义 ===*/
typedef enum
{
    MOTION_IDLE = 0,                    // 空闲
    MOTION_FORWARD,                     // 前进
    MOTION_BACKWARD,                    // 后退
    MOTION_TURN_LEFT,                   // 左转
    MOTION_TURN_RIGHT,                  // 右转
} Motion_Mode_t;

/*=== 全局状态结构 ===*/
typedef struct
{
    Motion_Mode_t motion_mode;          // 当前运动模式
    uint8_t motion_speed;               // 运动速度 (0-100)
    uint8_t base_speed;                 // 基础速度 (0-100)，用于键控时的默认速度
    uint8_t vacuum_enabled;             // 吸盘是否启用
    uint8_t vacuum_speed;               // 吸盘转速 (0-100)
    uint8_t key_control_mode;           // 键控模式 (0=OFF, 1=ON)
    uint8_t emergency_stop;             // 急停标志 (0=正常, 1=急停)
} BT_State_t;

/*=== 函数声明 ===*/

/**
 * @brief 蓝牙通信初始化
 */
void BT_Init(void);

/**
 * @brief 处理接收到的数据
 * @note 应该在主循环中调用
 */
void BT_Process(void);

/**
 * @brief 发送数据包
 * @param packet: 数据包指针
 */
void BT_SendPacket(const BT_Packet_t *packet);

/**
 * @brief 获取当前运动状态
 */
Motion_Mode_t BT_GetMotionMode(void);

/**
 * @brief 获取当前运动速度
 */
uint8_t BT_GetMotionSpeed(void);

/**
 * @brief 获取完整的蓝牙状态
 */
const BT_State_t* BT_GetState(void);

/**
 * @brief 直接设置吸盘转速（用于硬件K1同步状态）
 */
void BT_SetVacuumSpeedDirect(uint8_t speed_percent);

/**
 * @brief 获取当前设置的负压风扇转速百分比 (0-100)
 */
uint8_t BT_GetVacuumSpeed(void);

/**
 * @brief 处理键控模式切换（硬件K2直接调用）
 */
void BT_HandleKeyControlModeChange(uint8_t enabled);

/**
 * @brief 执行急停（全局生效）
 */
void BT_EmergencyStop(void);

/**
 * @brief 清除急停状态
 */
void BT_ClearEmergencyStop(void);

/**
 * @brief 检查是否处于急停状态
 */
uint8_t BT_IsEmergencyStopped(void);

/**
 * @brief 开启/关闭负压电机（全局生效）
 */
void BT_VacuumControl(uint8_t enable);

/**
 * @brief 设置负压电机转速（全局生效）
 */
void BT_VacuumSetSpeed(uint8_t speed);

#endif

/**
 * @file    CircleHandler.c
 * @brief   圆环元素检测与处理模块实现 (仅左环)
 * @details 基于编码器累计里程触发, 纯里程控制, 无角度积分
 *
 *          流程:
 *          1. 大圆环入环检测开始 → 左侧半侧追线
 *          2. 大圆环入环检测结束 → 恢复正常追线
 *          3. 大圆环出环检测开始 → 右侧半侧追线
 *          4. 大圆环出环检测结束 → 出环完成, 恢复正常
 *          4. 出环后开始检测停车区域 (十字路口横线)
 *          5. 检测到 3 根横线后立即抱死停车
 *          6. 停车 3s 后退出巡线模式
 */

#include "CircleHandler.h"
#include "BlackPoint_Finder.h"
#include "ADC_get.h"
#include "PID_Controller.h"
#include "Motor_ctr.h"
#include "M3PWM.h"
#include "RGB_Led.h"
#include "Odometer.h"
#include "SpeedProfile.h"
#include "RoutePoints.h"
#include <stdio.h>

/* ========================================================================== */
/*                              外部变量引用                                   */
/* ========================================================================== */
extern int16_t position_get;
extern volatile uint32_t g_systick_ms;
extern volatile uint32_t g_lose_time;
extern uint8_t star_car;

/* ========================================================================== */
/*                              可调参数                                       */
/* ========================================================================== */

/* ---- 大圆环检测窗口阈值 (mm) ---- */
#define CIRCLE_ENTRY_DETECT_START_MM  ROUTE_CIRCLE_ENTRY_DETECT_START_MM
#define CIRCLE_ENTRY_DETECT_STOP_MM   ROUTE_CIRCLE_ENTRY_DETECT_STOP_MM
#define CIRCLE_EXIT_DETECT_START_MM   ROUTE_CIRCLE_EXIT_DETECT_START_MM
#define CIRCLE_EXIT_DETECT_STOP_MM    ROUTE_CIRCLE_EXIT_DETECT_STOP_MM

/* 流程时间参数 */
#define PARKING_ENABLE_DELAY_MS  2000    /* 出环后 2s 开始检测停车 */
#define PARKING_STOP_DURATION_MS 3000    /* 停车持续 3s */
#define CROSSLINE_TARGET_COUNT   3       /* 需要检测到的横线数量 */


/* ========================================================================== */
/*                              序列阶段枚举                                   */
/* ========================================================================== */
typedef enum {
	PHASE_WAIT_ENTRY_DETECT = 0, /* 等待入环检测开始 */
	PHASE_WAIT_EXIT_DETECT,      /* 入环检测结束后, 等待出环检测开始 */
	PHASE_DONE                   /* 大圆环完成, 等待停车 */
} CirclePhase_t;

/* ========================================================================== */
/*                              内部状态变量                                   */
/* ========================================================================== */
static CircleState_t s_state = CIRCLE_STATE_NORMAL;

/* 序列阶段 */
static CirclePhase_t s_phase = PHASE_WAIT_ENTRY_DETECT;

/* 时序计时 */
static uint32_t s_left_exit_ms = 0;       /* 左环出环时间 */

/* 上一次 star_car 状态 (边沿检测) */
static uint8_t s_was_running = 0;

/* 停车检测 */
static uint8_t s_parking_detection_enabled = 0;
static uint8_t s_crossline_count = 0;
static uint8_t s_on_crossline = 0;        /* 当前正在横线上 (消抖) */
static uint8_t s_parking_stopped = 0;     /* 已触发停车 */
static uint32_t s_parking_stop_ms = 0;    /* 停车开始时间 */

/* 调试打印限流 */
static uint32_t s_last_print_ms = 0;

static void Circle_UpdateWindowLed(void)
{
	float loc = Odometer_GetLocation();
	uint8_t in_window = 0;

	if(loc >= ROUTE_TURN1_ENTER_MM && loc < ROUTE_TURN1_EXIT_MM) in_window = 1;
	if(loc >= ROUTE_SMALL_CIRCLE1_ENTER_MM && loc < ROUTE_SMALL_CIRCLE1_EXIT_MM) in_window = 1;
	if(loc >= ROUTE_TURN2_ENTER_MM && loc < ROUTE_TURN2_EXIT_MM) in_window = 1;
	if(loc >= ROUTE_SMALL_CIRCLE2_ENTER_MM && loc < ROUTE_SMALL_CIRCLE2_EXIT_MM) in_window = 1;
	if(loc >= CIRCLE_ENTRY_DETECT_START_MM && loc < CIRCLE_ENTRY_DETECT_STOP_MM) in_window = 1;
	if(loc >= CIRCLE_EXIT_DETECT_START_MM && loc < CIRCLE_EXIT_DETECT_STOP_MM) in_window = 1;

	if(in_window)
	{
		RGB_SetColor(RGB_COLOR_MAGENTA);
	}
	else
	{
		RGB_SetColor(RGB_COLOR_G);
	}
}

/* ========================================================================== */
/*                              公有函数实现                                   */
/* ========================================================================== */

void Circle_Init(void)
{
	s_state = CIRCLE_STATE_NORMAL;
	s_phase = PHASE_WAIT_ENTRY_DETECT;
	s_left_exit_ms = 0;
	s_was_running = 0;
	s_parking_detection_enabled = 0;
	s_crossline_count = 0;
	s_on_crossline = 0;
	s_parking_stopped = 0;
	s_parking_stop_ms = 0;
	s_last_print_ms = 0;
}

void Circle_Reset(void)
{
	if(s_state != CIRCLE_STATE_NORMAL)
	{
		printf("[CIRCLE] reset\r\n");
	}
	s_state = CIRCLE_STATE_NORMAL;
	s_phase = PHASE_WAIT_ENTRY_DETECT;
	s_left_exit_ms = 0;
	s_was_running = 0;
	s_parking_detection_enabled = 0;
	s_crossline_count = 0;
	s_on_crossline = 0;
	s_parking_stopped = 0;
	s_last_print_ms = 0;
}

CircleState_t Circle_GetState(void)
{
	return s_state;
}

uint8_t Circle_IsActive(void)
{
	return (s_state != CIRCLE_STATE_NORMAL) ? 1 : 0;
}

/**
 * @brief  检测横线 (十字路口停车区域)
 * @param  adc_values  传感器 ADC 值数组
 * @return 1=检测到横线, 0=未检测到
 * @details 利用传感器圆弧形状特征:
 *          对称外侧传感器对同时检测到黑线 → 横线
 *          检查 (0,15), (1,14), (2,13) 三对, 至少 2 对同时为黑
 */
static uint8_t Circle_DetectCrossLine(volatile uint16_t *adc_values)
{
	uint8_t pair_count = 0;

	if(BlackPoint_Finder_IsBlackPoint(0, adc_values[0]) &&
	   BlackPoint_Finder_IsBlackPoint(15, adc_values[15]))
		pair_count++;

	if(BlackPoint_Finder_IsBlackPoint(1, adc_values[1]) &&
	   BlackPoint_Finder_IsBlackPoint(14, adc_values[14]))
		pair_count++;

	if(BlackPoint_Finder_IsBlackPoint(2, adc_values[2]) &&
	   BlackPoint_Finder_IsBlackPoint(13, adc_values[13]))
		pair_count++;

	return (pair_count >= 2) ? 1 : 0;
}

/**
 * @brief  圆环状态机主更新函数
 */
void Circle_Update(volatile uint16_t *adc_values)
{
	BlackPointResult_t half_result;

	if(adc_values == NULL) return;

	/* ======== 停车状态处理 (最高优先级) ======== */
	if(s_parking_stopped)
	{
		if((g_systick_ms - s_parking_stop_ms) >= PARKING_STOP_DURATION_MS)
		{
			/* 3s 停车完成, 退出巡线模式 */
			s_parking_stopped = 0;
			star_car = 0;
			WheelLock_Disable();
			Motor_StopAll();
			Motor_Disable();
			M3PWM_SetDutyCycle(0);  /* 关闭负压风扇 */
			RGB_SetColor(RGB_COLOR_OFF);
			PID_PositionLoop_Enable(0);
			SpeedPID_ResetState();
			printf("[PKG] done\r\n");
		}
		else
		{
			Circle_UpdateWindowLed();
		}
		return;
	}

	/* ======== 急停/退出保护 ======== */
	if(!star_car)
	{
		if(s_state != CIRCLE_STATE_NORMAL)
		{
			s_state = CIRCLE_STATE_NORMAL;
		}
		s_was_running = 0;
		return;
	}

	/* ======== 启动边沿检测: star_car 0→1 ======== */
	if(!s_was_running)
	{
		s_was_running = 1;
		s_phase = PHASE_WAIT_ENTRY_DETECT;
		s_parking_detection_enabled = 0;
		s_crossline_count = 0;
		s_on_crossline = 0;
		Odometer_Reset();         /* 里程清零, 配合分段减速 */
		SpeedProfile_Reset();     /* 路段索引归零 */
		printf("[CIRCLE] start, entry[%.0f-%.0f] exit[%.0f-%.0f]\r\n",
			CIRCLE_ENTRY_DETECT_START_MM,
			CIRCLE_ENTRY_DETECT_STOP_MM,
			CIRCLE_EXIT_DETECT_START_MM,
			CIRCLE_EXIT_DETECT_STOP_MM);
	}

	/* ======== 停车区域检测 (左环出环后 2s 启用) ======== */
	if(s_parking_detection_enabled && s_state == CIRCLE_STATE_NORMAL)
	{
		uint8_t cross = Circle_DetectCrossLine(adc_values);

		if(cross)
		{
			if(!s_on_crossline)
			{
				/* 上升沿: 进入横线 */
				s_on_crossline = 1;
				s_crossline_count++;

				if(s_crossline_count >= CROSSLINE_TARGET_COUNT)
				{
					/* 达到 3 根横线, 立即抱死停车 */
					s_parking_stopped = 1;
					s_parking_stop_ms = g_systick_ms;
					s_parking_detection_enabled = 0;
					WheelLock_Enable();
					printf("[PKG] line 3/3 -> STOP\r\n");
					return;
				}
				printf("[PKG] line %d/3\r\n", s_crossline_count);
			}
		}
		else
		{
			s_on_crossline = 0;
		}
	}

	/* ======== 停车检测启用定时 (左环出环后 2s) ======== */
	if(s_phase == PHASE_DONE && !s_parking_detection_enabled && s_left_exit_ms != 0)
	{
		if((g_systick_ms - s_left_exit_ms) >= PARKING_ENABLE_DELAY_MS)
		{
			s_parking_detection_enabled = 1;
			s_crossline_count = 0;
			s_on_crossline = 0;

		}
	}

	/* ======== 状态机 ======== */
	switch(s_state)
	{
		/* ================================================================ */
		case CIRCLE_STATE_NORMAL:
		{
			/* 根据当前阶段决定行为 */
			switch(s_phase)
			{
				case PHASE_WAIT_ENTRY_DETECT:
				/* 等待里程达到入环检测开始点 */
				if(Odometer_GetLocation() >= CIRCLE_ENTRY_DETECT_START_MM)
				{
					s_state = CIRCLE_STATE_ENTERING;
					printf("[CIRCLE] %.0fmm: entry detect on (left)\r\n", Odometer_GetLocation());
				}
				break;

				case PHASE_WAIT_EXIT_DETECT:
				/* 等待里程达到出环检测开始点 */
				if(Odometer_GetLocation() >= CIRCLE_EXIT_DETECT_START_MM)
				{
					s_state = CIRCLE_STATE_EXITING;
					printf("[CIRCLE] %.0fmm: exit detect on (right)\r\n", Odometer_GetLocation());
				}
					break;

				case PHASE_DONE:
					/* 大圆环已完成, 不再处理 */
					break;
			}
			break;
		}

		/* ================================================================ */
		case CIRCLE_STATE_ENTERING:
		{
			/* 左半侧追线: 直线正常走, 岔路时自动选左侧 */
			BlackPoint_Finder_SearchHalf(adc_values, 0, &half_result);
			if(half_result.found)
			{
				position_get = (int16_t)(half_result.precise_position * 10.0f);
				g_lose_time = 0;
			}
			else
			{
				/* 半侧丢线, 全幅兜底 */
				BlackPointResult_t full_result;
				BlackPoint_Finder_Search(adc_values, &full_result);
				if(full_result.found)
				{
					position_get = (int16_t)(full_result.precise_position * 10.0f);
					g_lose_time = 0;
				}
			}

			/* 入环检测窗口结束 → 恢复正常追线 */
			{
				float loc = Odometer_GetLocation();
				if(loc >= CIRCLE_ENTRY_DETECT_STOP_MM)
				{
					s_state = CIRCLE_STATE_NORMAL;
					s_phase = PHASE_WAIT_EXIT_DETECT;
					printf("[CIRCLE] %.0fmm: entry detect off (normal)\r\n", loc);
				}
			}
			break;
		}

		/* ================================================================ */
		case CIRCLE_STATE_EXITING:
		{
			/* 出环引导: 右半侧追线, 岔路时自动选右侧 */
			BlackPoint_Finder_SearchHalf(adc_values, 1, &half_result);
			if(half_result.found)
			{
				position_get = (int16_t)(half_result.precise_position * 10.0f);
				g_lose_time = 0;
			}
			else
			{
				/* 半侧丢线, 全幅兜底 */
				BlackPointResult_t full_result;
				BlackPoint_Finder_Search(adc_values, &full_result);
				if(full_result.found)
				{
					position_get = (int16_t)(full_result.precise_position * 10.0f);
					g_lose_time = 0;
				}
			}

			/* 出环检测窗口结束 → 恢复正常追线并标记完成 */
			{
				float loc = Odometer_GetLocation();
				if(loc >= CIRCLE_EXIT_DETECT_STOP_MM)
				{
					s_state = CIRCLE_STATE_NORMAL;
					s_left_exit_ms = g_systick_ms;
					s_phase = PHASE_DONE;
					printf("[CIRCLE] %.0fmm: exit detect off (normal)\r\n", loc);
				}
			}
			break;
		}

		default:
			s_state = CIRCLE_STATE_NORMAL;
			break;
	}

		Circle_UpdateWindowLed();
}

#ifndef __CIRCLE_HANDLER_H__
#define __CIRCLE_HANDLER_H__

#include "stm32f10x.h"
#include <stdint.h>

/**
 * @file    CircleHandler.h
 * @brief   圆环元素检测与处理模块
 * @details 使用状态机 + 里程触发实现圆环的驶入、绕行、驶出
 *
 *          状态转移:
 *          NORMAL → 里程达到入环阈値 → ENTERING
 *          ENTERING → 里程达到出环偷向阈値 → EXITING
 *          EXITING → 里程达到出环阈値 → NORMAL
 */

/* 圆环状态机状态 */
typedef enum {
	CIRCLE_STATE_NORMAL = 0,    /* 正常巡线 */
	CIRCLE_STATE_ENTERING,      /* 正在驶入圆环 (左側半幅追线) */
	CIRCLE_STATE_IN_CIRCLE,     /* 保留，实际不使用 */
	CIRCLE_STATE_EXITING        /* 正在驶出圆环 (右側半幅追线) */
} CircleState_t;

/**
 * @brief  初始化圆环处理模块
 */
void Circle_Init(void);

/**
 * @brief  重置圆环状态机为 NORMAL
 */
void Circle_Reset(void);

/**
 * @brief  获取当前圆环状态
 * @return 当前状态
 */
CircleState_t Circle_GetState(void);

/**
 * @brief  圆环状态机更新 (在 SysTick 中断中调用, 2ms 周期)
 * @param  adc_values  传感器 ADC 值数组
 */
void Circle_Update(volatile uint16_t *adc_values);

/**
 * @brief  查询当前是否处于圆环处理模式 (非 NORMAL)
 * @return 1=正在处理圆环, 0=正常巡线
 */
uint8_t Circle_IsActive(void);

#endif /* __CIRCLE_HANDLER_H__ */

#include "Key_Scan.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

extern volatile uint32_t g_systick_ms;

// 按键GPIO定义
#define KEY_K1_PORT    GPIOA
#define KEY_K1_PIN     GPIO_Pin_5
#define KEY_K1_RCC     RCC_APB2Periph_GPIOA

#define KEY_K2_PORT    GPIOA
#define KEY_K2_PIN     GPIO_Pin_4
#define KEY_K2_RCC     RCC_APB2Periph_GPIOA

#define KEY_K3_PORT    GPIOC
#define KEY_K3_PIN     GPIO_Pin_14
#define KEY_K3_RCC     RCC_APB2Periph_GPIOC

#define KEY_K4_PORT    GPIOC
#define KEY_K4_PIN     GPIO_Pin_13
#define KEY_K4_RCC     RCC_APB2Periph_GPIOC

// 按键内部状态结构
typedef struct {
    uint8_t stable_state;       // 去抖后的稳定状态
    uint8_t last_raw_state;     // 上次扫描的原始状态
    uint32_t change_start_time; // 状态变化开始时间
} Key_Status_t;

// 按键状态数组
static Key_Status_t key_status[4] = {0};

// 消抖时间 (ms)
#define KEY_DEBOUNCE_MS     20

// 按键事件队列（最多缓存4个事件）
#define KEY_EVENT_BUFFER_SIZE   4
static Key_Event_t key_event_buffer[KEY_EVENT_BUFFER_SIZE];
static uint8_t event_write_index = 0;
static uint8_t event_read_index = 0;
static uint8_t event_count = 0;

// 读取按键原始状态（低电平有效）
static inline uint8_t Key_ReadRaw(Key_ID_t key_id)
{
    uint8_t state = 0;

    switch(key_id)
    {
        case KEY_K1:
            state = (GPIO_ReadInputDataBit(KEY_K1_PORT, KEY_K1_PIN) == Bit_RESET) ? 1 : 0;
            break;
        case KEY_K2:
            state = (GPIO_ReadInputDataBit(KEY_K2_PORT, KEY_K2_PIN) == Bit_RESET) ? 1 : 0;
            break;
        case KEY_K3:
            state = (GPIO_ReadInputDataBit(KEY_K3_PORT, KEY_K3_PIN) == Bit_RESET) ? 1 : 0;
            break;
        case KEY_K4:
            state = (GPIO_ReadInputDataBit(KEY_K4_PORT, KEY_K4_PIN) == Bit_RESET) ? 1 : 0;
            break;
        default:
            break;
    }

    return state;
}

// 添加事件到队列
static void Key_AddEvent(Key_ID_t key_id)
{
    if(event_count >= KEY_EVENT_BUFFER_SIZE)
    {
        return; // 事件队列已满，丢弃事件
    }

    key_event_buffer[event_write_index].key_id = key_id;

    event_write_index = (event_write_index + 1) % KEY_EVENT_BUFFER_SIZE;
    event_count++;
}

// 初始化按键扫描
void Key_Scan_Init(void)
{
    GPIO_InitTypeDef GPIO_InitStructure;

    // 使能GPIO时钟
    RCC_APB2PeriphClockCmd(KEY_K1_RCC | KEY_K2_RCC | KEY_K3_RCC | KEY_K4_RCC | RCC_APB2Periph_AFIO, ENABLE);

    // 配置K1 (PA5) 和 K2 (PA4) 为上拉输入
    GPIO_InitStructure.GPIO_Pin = KEY_K1_PIN | KEY_K2_PIN;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;  // 上拉输入
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(KEY_K1_PORT, &GPIO_InitStructure);

    // 配置K3 (PC14) 和 K4 (PC13) 为上拉输入
    GPIO_InitStructure.GPIO_Pin = KEY_K3_PIN;
    GPIO_Init(GPIOC, &GPIO_InitStructure);

    GPIO_InitStructure.GPIO_Pin = KEY_K4_PIN;
    GPIO_Init(GPIOC, &GPIO_InitStructure);

    // 初始化状态
    {
        uint8_t i;
        for(i = 0; i < 4; i++)
        {
            uint8_t raw = Key_ReadRaw((Key_ID_t)(i + 1));
            key_status[i].stable_state = raw;
            key_status[i].last_raw_state = raw;
            key_status[i].change_start_time = g_systick_ms;
        }
    }

    // 初始化事件队列
    event_write_index = 0;
    event_read_index = 0;
    event_count = 0;
}

// 按键扫描更新（非阻塞，需要周期性调用）
void Key_Scan_Update(void)
{
    Key_ID_t key_ids[] = {KEY_K1, KEY_K2, KEY_K3, KEY_K4};
    uint8_t i;

    for(i = 0; i < 4; i++)
    {
        Key_ID_t key_id = key_ids[i];
        Key_Status_t *status = &key_status[i]; // 定义 status 指针

        // 读取当前状态
        uint8_t raw_state = Key_ReadRaw(key_id);

        // 状态发生变化（与上一帧相比）
        if(raw_state != status->last_raw_state)
        {
            status->change_start_time = g_systick_ms;
        }

        // 检查状态是否稳定
        if((g_systick_ms - status->change_start_time) >= KEY_DEBOUNCE_MS)
        {
            // 如果稳定状态与当前读取状态不一致，说明发生了有效的状态改变
            if(raw_state != status->stable_state)
            {
                // 检测释放事件：从按下(1)变到释放(0)
                if(status->stable_state == 1 && raw_state == 0)
                {
                    Key_AddEvent(key_id);
                }
                status->stable_state = raw_state;
            }
        }

        // 更新上一帧原始状态
        status->last_raw_state = raw_state;
    }
}

// 获取按键当前状态
uint8_t Key_GetState(Key_ID_t key_id)
{
    if(key_id < KEY_K1 || key_id > KEY_K4)
    {
        return 0;
    }

    // 返回去抖后的稳定状态
    return key_status[key_id - 1].stable_state;
}

// 获取按键事件
Key_Event_t* Key_GetEvent(void)
{
    if(event_count == 0)
    {
        return 0;  // 无事件
    }

    Key_Event_t *event = &key_event_buffer[event_read_index];
    event_read_index = (event_read_index + 1) % KEY_EVENT_BUFFER_SIZE;
    event_count--;

    return event;
}

// 检查是否有按键事件
uint8_t Key_HasEvent(void)
{
    return (event_count > 0) ? 1 : 0;
}

// 清除所有按键事件
void Key_ClearEvent(void)
{
    event_read_index = 0;
    event_write_index = 0;
    event_count = 0;
}

