int main(void)
{
	/* ====== 外设初始化 ====== */
	RGB_Init();
	LSM6DSR_Init();
	M3PWM_Init();
	SysTick_Init();
	Motor_Init();
	M3PWM_Start();
	ABEncoder_Init();
	BlackPoint_Finder_Init();
	MuxADC_Init();
	Key_Scan_Init();
	Uart2_Init(115200);
	BT_Init();
	PID_Init();
	Odometer_Init();  /* 初始化里程计模块 */
	SpeedProfile_Init();  /* 初始化分段减速模块 */
	Circle_Init();    /* 初始化圆环检测模块 */

	/* ====== 初始状态: 等待按键启动 ====== */
	PID_PositionLoop_Enable(0);

	/* ====== 主循环 ====== */
	while(1)
	{
		/* 喂狗: 主循环正在运行 */
		g_main_loop_watchdog = g_systick_ms;

		/* 按键扫描与蓝牙处理 */
		Key_Scan_Update();
		BT_Process();

		/* 读取电池电压
		 * 校准说明: 真实7.36V时显示7.76V, 偏高0.4V
		 * 以低电压(7.4V附近)为基准调整系数: 0.0038 * (7.36/7.76) ≈ 0.00360 */
		BDI_V = (float)g_mux_adc_values[16] * 0.003605f;

		/* ====== 光电管校准: 持续采样更新最小/最大值 ====== */
		if(g_calibrating)
		{
			uint8_t ci;
			for(ci = 0; ci < SENSOR_COUNT; ci++)
			{
				uint16_t val = g_mux_adc_values[ci];
				if(val < g_cal_min[ci]) g_cal_min[ci] = val;
				if(val > g_cal_max[ci]) g_cal_max[ci] = val;
			}
		}

		/* ====== 低电压警告检测 (带消抖和滞回) ====== */
		if(BDI_V > 0.5f && BDI_V < LOW_BATTERY_THRESHOLD)
		{
			/* 电压低于阈值, 增加消抖计数 */
			if(g_low_battery_debounce < LOW_BATTERY_DEBOUNCE_CNT)
			{
				g_low_battery_debounce++;
			}
			else if(!g_low_battery_flag)
			{
				/* 连续低电压达到阈值, 确认低电压状态 */
				g_low_battery_flag = 1;
				g_low_battery_msg_timer = 0;  /* 立即发送第一条警告 */
			}
		}
		else if(BDI_V >= LOW_BATTERY_RECOVER_TH)
		{
			/* 电压高于恢复阈值, 清除消抖计数 */
			g_low_battery_debounce = 0;

			if(g_low_battery_flag)
			{
				/* 电压恢复正常, 清除低电压标志 */
				g_low_battery_flag = 0;
				RGB_SetColor(RGB_COLOR_OFF);
				printf("Battery voltage recovered: %.2fV\r\n", BDI_V);
			}
		}

		/* 低电压状态下的LED闪烁和消息发送 */
		if(g_low_battery_flag)
		{
			/* LED红色闪烁 (最醒目) */
			if((g_systick_ms - g_low_battery_led_timer) >= LOW_BATTERY_LED_PERIOD_MS)
			{
				g_low_battery_led_timer = g_systick_ms;
				g_low_battery_led_state = !g_low_battery_led_state;

				if(g_low_battery_led_state)
				{
					RGB_SetColor(RGB_COLOR_R);  /* 红色亮 */
				}
				else
				{
					RGB_SetColor(RGB_COLOR_OFF);  /* 灭 */
				}
			}

			/* 定期发送低电压警告消息 */
			if((g_systick_ms - g_low_battery_msg_timer) >= LOW_BATTERY_MSG_PERIOD_MS)
			{
				g_low_battery_msg_timer = g_systick_ms;
				printf("[WARNING] Low Battery! Voltage: %.2fV (Threshold: %.1fV)\r\n", BDI_V, LOW_BATTERY_THRESHOLD);
				printf("Please charge immediately to avoid over-discharge!\r\n");
			}
		}

		/* 处理按键事件 */
		Key_Event_t *event = Key_GetEvent();
		if(event != NULL)
		{
			HandleKeyEvent(event);
		}

		/* 蓝牙遥控模式: 应用运动指令 */
		if(g_bt_key_control_mode)
		{
			const BT_State_t *state = BT_GetState();
			BT_ApplyMotion(state);
		}
	}
}

#include "Motor_ctr.h"

// 全局变量
static uint32_t g_motor_frequency = MOTOR_FREQUENCY_17KHZ;  // 当前PWM频率
static uint16_t g_motor1_duty = 0;                          // 电机1当前占空比
static uint16_t g_motor2_duty = 0;                          // 电机2当前占空比
static uint8_t g_motor1_direction = MOTOR_DIR_FORWARD;      // 电机1当前方向
static uint8_t g_motor2_direction = MOTOR_DIR_FORWARD;      // 电机2当前方向
uint16_t uart_rev_tiem = 0;
/**
 * @brief  电机初始化函数
 * @note   配置PA12为电机使能，PA8/PA10为方向控制，PA9/PA11为PWM输出
 * @param  无
 * @retval 无
 */
void Motor_Init(void)
{
    // 开启时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);  // 开启GPIOA和AFIO时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_TIM1, ENABLE);                         // 开启TIM1时钟

    // GPIO配置 - 电机使能引脚PA12
    GPIO_InitTypeDef GPIO_InitStructure;
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_12;           // PA12 - 电机使能
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;     // 推挽输出
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    // 50MHz速度
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    // GPIO配置 - 电机方向控制引脚PA8和PA10
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_8 | GPIO_Pin_10;  // PA8 - 电机1方向, PA10 - 电机2方向
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;     // 推挽输出
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    // 50MHz速度
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    // GPIO配置 - PWM输出引脚PA9和PA11
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9 | GPIO_Pin_11;  // PA9 - 电机1 PWM, PA11 - 电机2 PWM
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;      // 复用推挽输出
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;    // 50MHz速度
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    // TIM1时基配置 - 17KHz频率计算
    // 频率 = 72MHz / ((PSC + 1) × (ARR + 1))
    // 17KHz = 72000000 / ((0 + 1) × (4234 + 1)) = 72000000 / 4235 ≈ 17000Hz
    TIM_TimeBaseInitTypeDef TIM_TimeBaseStructure;
    TIM_TimeBaseStructure.TIM_Period = 4234;             // ARR值，决定PWM周期 (4234 + 1 = 4235)
    TIM_TimeBaseStructure.TIM_Prescaler = 0;             // PSC值，决定时钟分频 (0 + 1 = 1)
    TIM_TimeBaseStructure.TIM_ClockDivision = TIM_CKD_DIV1;  // 时钟分频因子
    TIM_TimeBaseStructure.TIM_CounterMode = TIM_CounterMode_Up;  // 向上计数模式
    TIM_TimeBaseStructure.TIM_RepetitionCounter = 0;     // 重复计数器值
    TIM_TimeBaseInit(TIM1, &TIM_TimeBaseStructure);

    // TIM1通道2 PWM配置 (电机1 - PA9)
    TIM_OCInitTypeDef TIM_OCInitStructure;
    TIM_OCInitStructure.TIM_OCMode = TIM_OCMode_PWM1;    // PWM模式1
    TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;  // 输出使能
    TIM_OCInitStructure.TIM_OutputNState = TIM_OutputNState_Disable;  // 互补输出禁用
    TIM_OCInitStructure.TIM_Pulse = 0;                   // CCR值，初始占空比为0
    TIM_OCInitStructure.TIM_OCPolarity = TIM_OCPolarity_High;  // 输出极性为高
    TIM_OCInitStructure.TIM_OCNPolarity = TIM_OCNPolarity_High;  // 互补输出极性
    TIM_OCInitStructure.TIM_OCIdleState = TIM_OCIdleState_Reset;  // 空闲状态输出
    TIM_OCInitStructure.TIM_OCNIdleState = TIM_OCNIdleState_Reset;  // 空闲状态互补输出
    TIM_OC2Init(TIM1, &TIM_OCInitStructure);             // 初始化通道2

    // TIM1通道4 PWM配置 (电机2 - PA11)
    TIM_OCInitStructure.TIM_Pulse = 0;                   // CCR值，初始占空比为0
    TIM_OC4Init(TIM1, &TIM_OCInitStructure);             // 初始化通道4

    // 使能TIM1的PWM输出
    TIM_CtrlPWMOutputs(TIM1, ENABLE);

    // 启动TIM1
    TIM_Cmd(TIM1, ENABLE);
    Motor_SetDirection(MOTOR_R,0);
		Motor_SetDirection(MOTOR_L,0);
    // 初始化电机状态
    Motor_Disable();  // 初始状态禁用电机
    Motor_StopAll();  // 停止所有电机
}

/**
 * @brief  使能电机
 * @note   设置PA12为高电平
 * @param  无
 * @retval 无
 */
void Motor_Enable(void)
{
    GPIO_SetBits(GPIOA, GPIO_Pin_12);
}

/**
 * @brief  禁用电机
 * @note   设置PA12为低电平
 * @param  无
 * @retval 无
 */
void Motor_Disable(void)
{
    GPIO_ResetBits(GPIOA, GPIO_Pin_12);
}

/**
 * @brief  设置电机速度
 * @note   占空比范围0-10000
 * @param  motor_id: 电机编号 (MOTOR_R 或 MOTOR_L)
 * @param  duty: 占空比值 (0-10000)
 * @retval 无
 */
void Motor_SetSpeed(uint8_t motor_id, uint16_t duty)
{
    uint16_t compare_value;

    // 限制占空比范围
    if(duty > MOTOR_DUTY_MAX) duty = MOTOR_DUTY_MAX;

    // 计算比较值 (将0-10000映射到0-4234)
    compare_value = (uint16_t)((TIM1->ARR + 1) * duty / MOTOR_DUTY_MAX);

    switch(motor_id)
    {
        case MOTOR_R:
            g_motor1_duty = duty;
            TIM_SetCompare2(TIM1, compare_value);  // 通道2 - 电机1
            break;

        case MOTOR_L:
            g_motor2_duty = duty;
            TIM_SetCompare4(TIM1, compare_value);  // 通道4 - 电机2
            break;

        default:
            break;
    }
}

/**
 * @brief  设置电机方向
 * @note   设置对应的方向引脚
 * @param  motor_id: 电机编号 (MOTOR_R 或 MOTOR_L)
 * @param  direction: 方向 (MOTOR_DIR_FORWARD 或 MOTOR_DIR_BACKWARD)
 * @retval 无
 */
void Motor_SetDirection(uint8_t motor_id, uint8_t direction)
{
    switch(motor_id)
    {
        case MOTOR_R:
            g_motor1_direction = direction;
            if(direction == MOTOR_DIR_FORWARD)
            {
                GPIO_SetBits(GPIOA, GPIO_Pin_8);     // PA8高电平 - 电机1正转
            }
            else
            {
                GPIO_ResetBits(GPIOA, GPIO_Pin_8);   // PA8低电平 - 电机1反转
            }
            break;

        case MOTOR_L:
            g_motor2_direction = direction;
            if(direction != MOTOR_DIR_FORWARD)
            {
                GPIO_SetBits(GPIOA, GPIO_Pin_10);    // PA10高电平 - 电机2正转
            }
            else
            {
                GPIO_ResetBits(GPIOA, GPIO_Pin_10);  // PA10低电平 - 电机2反转
            }
            break;

        default:
            break;
    }
}

uint16_t Motor_GetDuty(uint8_t motor_id)
{
    if(motor_id == MOTOR_R)
    {
        return g_motor1_duty;
    }
    else if(motor_id == MOTOR_L)
    {
        return g_motor2_duty;
    }
    return 0;
}

uint8_t Motor_GetDirection(uint8_t motor_id)
{
    if(motor_id == MOTOR_R)
    {
        return g_motor1_direction;
    }
    else if(motor_id == MOTOR_L)
    {
        return g_motor2_direction;
    }
    return MOTOR_DIR_FORWARD;
}

/**
 * @brief  停止指定电机
 * @note   设置PWM占空比为0
 * @param  motor_id: 电机编号 (MOTOR_R 或 MOTOR_L)
 * @retval 无
 */
void Motor_Stop(uint8_t motor_id)
{
    Motor_SetSpeed(motor_id, 0);
}

/**
 * @brief  停止所有电机
 * @note   设置所有电机PWM占空比为0
 * @param  无
 * @retval 无
 */
void Motor_StopAll(void)
{
    Motor_Stop(MOTOR_R);
    Motor_Stop(MOTOR_L);
}

/**
 * @brief  设置PWM频率
 * @note   频率范围1Hz-1MHz
 * @param  freq: 频率值 (Hz)
 * @retval 无
 */
void Motor_SetFrequency(uint32_t freq)
{
    uint32_t psc, arr;
    uint32_t timer_clock = 72000000;  // TIM1时钟频率72MHz (APB2)

    // 限制频率范围
    if(freq < 1) freq = 1;
    if(freq > 1000000) freq = 1000000;

    g_motor_frequency = freq;

    // 计算预分频值和自动重装值
    // 频率 = 定时器时钟 / ((PSC + 1) × (ARR + 1))
    // 为了获得最佳精度，先计算PSC，再计算ARR
    psc = timer_clock / (freq * 1000) - 1;  // 目标ARR约为1000
    if(psc > 65535) psc = 65535;

    arr = timer_clock / (freq * (psc + 1)) - 1;
    if(arr > 65535) arr = 65535;

    // 更新定时器配置
    TIM_PrescalerConfig(TIM1, psc, TIM_PSCReloadMode_Immediate);
    TIM_SetAutoreload(TIM1, arr);

    // 重新设置电机速度以保持占空比
    Motor_SetSpeed(MOTOR_R, g_motor1_duty);
    Motor_SetSpeed(MOTOR_L, g_motor2_duty);
}

/**
 * @file    Odometer.c
 * @brief   里程计模块实现
 * @details 基于编码器和陀螺仪实现位置跟踪
 */

#include "Odometer.h"
#include "ABEncoder.h"
#include "LSM6DSR_Config.h"
#include <math.h>
#include <stddef.h>

/* ========================================================================== */
/*                              私有宏定义                                     */
/* ========================================================================== */

#define PI              3.14159265358979f
#define DEG_TO_RAD      (PI / 180.0f)
#define RAD_TO_DEG      (180.0f / PI)
#define DT              0.002f              /* SysTick 周期: 2ms */

/* ========================================================================== */
/*                              私有变量                                       */
/* ========================================================================== */

/* 里程计状态 */
static Odometer_Data_t s_odom_data = {0};

/* 上一次的编码器值 */
static int32_t s_last_left_cnt = 0;
static int32_t s_last_right_cnt = 0;

/* 陀螺仪融合参数 */
static uint8_t s_gyro_fusion_enabled = 1;   /* 默认启用陀螺仪融合 */
static float s_gyro_fusion_weight = 0.9f;   /* 陀螺仪权重 */

/* 校准状态 */
static Odometer_Calibration_t s_calibration = {0};

/* 当前使用的编码器参数 (可在运行时更新) */
static float s_pulse_per_mm = ODOM_ENCODER_PULSE_PER_MM;

/* ========================================================================== */
/*                              私有函数                                       */
/* ========================================================================== */

/**
 * @brief  角度归一化到 -180 ~ 180 度
 */
static float NormalizeAngle(float angle)
{
    while(angle > 180.0f) angle -= 360.0f;
    while(angle < -180.0f) angle += 360.0f;
    return angle;
}

/* ========================================================================== */
/*                              公有函数实现                                   */
/* ========================================================================== */

void Odometer_Init(void)
{
    /* 清零所有数据 */
    s_odom_data.location = 0.0f;
    s_odom_data.x = 0.0f;
    s_odom_data.y = 0.0f;
    s_odom_data.theta = 0.0f;

    /* 记录当前编码器值 */
    s_last_left_cnt = left_ecoder_cnt;
    s_last_right_cnt = right_ecoder_cnt;

    /* 默认启用陀螺仪融合 */
    s_gyro_fusion_enabled = 1;
    s_gyro_fusion_weight = 0.9f;

    /* 使用默认校准参数 */
    s_pulse_per_mm = ODOM_ENCODER_PULSE_PER_MM;

    /* 清除校准状态 */
    s_calibration.active = 0;
}

void Odometer_Update(void)
{
    /* 获取编码器增量 */
    int32_t left_delta = left_ecoder_cnt - s_last_left_cnt;
    int32_t right_delta = right_ecoder_cnt - s_last_right_cnt;

    s_last_left_cnt = left_ecoder_cnt;
    s_last_right_cnt = right_ecoder_cnt;

    /* 计算左右轮位移 (mm) */
    float left_dist = (float)left_delta / s_pulse_per_mm;
    float right_dist = (float)right_delta / s_pulse_per_mm;

    /* 计算中心位移 (两轮平均) */
    float center_dist = (left_dist + right_dist) / 2.0f;

    /* 累计行驶距离 (取绝对值累加) */
    s_odom_data.location += fabsf(center_dist);

    /* -------------------------------------------------------------------- */
    /*                         航向角更新                                    */
    /* -------------------------------------------------------------------- */

    /* 方法1: 使用编码器差速计算航向变化 */
    float delta_theta_encoder = (right_dist - left_dist) / ODOM_WHEEL_BASE_MM;
    delta_theta_encoder *= RAD_TO_DEG;  /* 转换为度 */

    /* 方法2: 使用陀螺仪积分 */
    float delta_theta_gyro = 0.0f;
    if(s_gyro_fusion_enabled)
    {
        /* 陀螺仪 Z 轴角速度积分 (LSE6DSR_data.gz_rads 单位: rad/s) */
        delta_theta_gyro = LSE6DSR_data.gz_rads * DT * RAD_TO_DEG;
    }

    /* 融合两种航向估计 */
    float delta_theta;
    if(s_gyro_fusion_enabled)
    {
        /* 互补滤波融合: 陀螺仪权重 + 编码器权重 */
        delta_theta = s_gyro_fusion_weight * delta_theta_gyro + 
                      (1.0f - s_gyro_fusion_weight) * delta_theta_encoder;
    }
    else
    {
        /* 仅使用编码器 */
        delta_theta = delta_theta_encoder;
    }

    /* 更新航向角 */
    s_odom_data.theta += delta_theta;
    s_odom_data.theta = NormalizeAngle(s_odom_data.theta);

    /* -------------------------------------------------------------------- */
    /*                         位置坐标更新                                  */
    /* -------------------------------------------------------------------- */

    /* 使用中点积分法更新位置 */
    /* 使用更新前后航向角的中点作为这段位移的方向 */
    float mid_theta = (s_odom_data.theta - delta_theta / 2.0f) * DEG_TO_RAD;

    s_odom_data.x += center_dist * cosf(mid_theta);
    s_odom_data.y += center_dist * sinf(mid_theta);
}

void Odometer_Reset(void)
{
    /* 完全重置 */
    s_odom_data.location = 0.0f;
    s_odom_data.x = 0.0f;
    s_odom_data.y = 0.0f;
    s_odom_data.theta = 0.0f;

    /* 更新编码器参考值 */
    s_last_left_cnt = left_ecoder_cnt;
    s_last_right_cnt = right_ecoder_cnt;
}

void Odometer_ResetCoordinate(void)
{
    /* 仅重置坐标，保留里程 */
    s_odom_data.x = 0.0f;
    s_odom_data.y = 0.0f;
    s_odom_data.theta = 0.0f;

    /* 更新编码器参考值 */
    s_last_left_cnt = left_ecoder_cnt;
    s_last_right_cnt = right_ecoder_cnt;
}

float Odometer_GetLocation(void)
{
    return s_odom_data.location;
}

float Odometer_GetX(void)
{
    return s_odom_data.x;
}

float Odometer_GetY(void)
{
    return s_odom_data.y;
}

float Odometer_GetTheta(void)
{
    return s_odom_data.theta;
}

void Odometer_GetData(Odometer_Data_t *data)
{
    if(data != NULL)
    {
        data->location = s_odom_data.location;
        data->x = s_odom_data.x;
        data->y = s_odom_data.y;
        data->theta = s_odom_data.theta;
    }
}

/* ========================================================================== */
/*                              校准函数实现                                   */
/* ========================================================================== */

void Odometer_StartCalibration(void)
{
    s_calibration.active = 1;
    s_calibration.start_left_cnt = left_ecoder_cnt;
    s_calibration.start_right_cnt = right_ecoder_cnt;
}

float Odometer_EndCalibration(float actual_distance_mm)
{
    if(!s_calibration.active || actual_distance_mm <= 0.0f)
    {
        s_calibration.active = 0;
        return 0.0f;
    }

    /* 计算校准期间的编码器脉冲数 */
    int32_t left_pulses = left_ecoder_cnt - s_calibration.start_left_cnt;
    int32_t right_pulses = right_ecoder_cnt - s_calibration.start_right_cnt;

    /* 取绝对值 (可能是倒车) */
    if(left_pulses < 0) left_pulses = -left_pulses;
    if(right_pulses < 0) right_pulses = -right_pulses;

    /* 计算平均脉冲数 */
    float avg_pulses = (float)(left_pulses + right_pulses) / 2.0f;

    /* 计算每毫米的脉冲数 */
    float new_pulse_per_mm = avg_pulses / actual_distance_mm;

    /* 更新运行时参数 */
    s_pulse_per_mm = new_pulse_per_mm;

    /* 结束校准 */
    s_calibration.active = 0;

    return new_pulse_per_mm;
}

uint8_t Odometer_IsCalibrating(void)
{
    return s_calibration.active;
}

int32_t Odometer_GetCalibrationPulseCount(void)
{
    if(!s_calibration.active) return 0;

    int32_t left_pulses = left_ecoder_cnt - s_calibration.start_left_cnt;
    int32_t right_pulses = right_ecoder_cnt - s_calibration.start_right_cnt;

    /* 取绝对值 */
    if(left_pulses < 0) left_pulses = -left_pulses;
    if(right_pulses < 0) right_pulses = -right_pulses;

    return (left_pulses + right_pulses) / 2;
}

/* ========================================================================== */
/*                              陀螺仪融合设置                                 */
/* ========================================================================== */

void Odometer_EnableGyroFusion(uint8_t enable)
{
    s_gyro_fusion_enabled = enable;
}

void Odometer_SetGyroFusionWeight(float weight)
{
    if(weight < 0.0f) weight = 0.0f;
    if(weight > 1.0f) weight = 1.0f;
    s_gyro_fusion_weight = weight;
}

/**
 * @file    Odometer.h
 * @brief   里程计模块 - 累计行驶距离与坐标定位
 * @details 基于编码器和陀螺仪实现:
 *          - 累计行驶距离 (location)
 *          - 二维坐标定位 (x, y)
 *          - 航向角跟踪 (theta)
 *          
 * 使用方法:
 *          1. 在初始化时调用 Odometer_Init()
 *          2. 在 SysTick 中断中调用 Odometer_Update()
 *          3. 调用 Odometer_Reset() 重置坐标系到当前位置
 *          4. 使用 Odometer_GetXXX() 函数获取位置信息
 *          
 * 校准方法:
 *          1. 测量小车直线行驶一段已知距离 (如 1000mm)
 *          2. 读取编码器累计脉冲数
 *          3. 计算: ENCODER_PULSE_PER_MM = 脉冲数 / 实际距离(mm)
 *          4. 更新 ODOM_ENCODER_PULSE_PER_MM 宏定义
 *          
 *          或者使用自动校准:
 *          1. 调用 Odometer_StartCalibration() 开始校准
 *          2. 手动推动小车直线行驶已知距离
 *          3. 调用 Odometer_EndCalibration(distance_mm) 传入实际距离
 *          4. 读取校准结果用于更新代码
 */

#ifndef __ODOMETER_H
#define __ODOMETER_H

#include "stm32f10x.h"

/* ========================================================================== */
/*                              校准参数配置                                   */
/* ========================================================================== */

/**
 * @brief  编码器每毫米脉冲数
 * @note   需要根据实际测量校准:
 *         - 编码器线数 (如 13线)
 *         - 电机减速比 (如 30:1)
 *         - 轮胎直径 (如 42mm)
 *         
 *         理论计算:
 *         pulse_per_rev = 编码器线数 × 4 × 减速比 = 13 × 4 × 30 = 1560
 *         wheel_circumference = π × 直径 = 3.14159 × 42 = 131.95mm
 *         ENCODER_PULSE_PER_MM = 1560 / 131.95 ≈ 11.82
 *         
 *         实际校准更准确!
 */
#define ODOM_ENCODER_PULSE_PER_MM   38.897f

/**
 * @brief  左右轮轴距 (单位: mm)
 * @note   两轮中心之间的距离，用于差速转向计算
 *         需要测量实际值并更新
 */
#define ODOM_WHEEL_BASE_MM          155.0f

/* ========================================================================== */
/*                              数据结构定义                                   */
/* ========================================================================== */

/**
 * @brief  里程计数据结构
 */
typedef struct {
    float location;     /* 累计行驶距离 (mm)，始终为正，表示总里程 */
    float x;            /* X坐标 (mm)，以 Reset 点为原点 */
    float y;            /* Y坐标 (mm)，以 Reset 点为原点 */
    float theta;        /* 航向角 (度)，以 Reset 时的方向为 0 度 */
} Odometer_Data_t;

/**
 * @brief  校准状态结构
 */
typedef struct {
    uint8_t active;              /* 校准是否激活 */
    int32_t start_left_cnt;      /* 校准开始时左轮编码器值 */
    int32_t start_right_cnt;     /* 校准开始时右轮编码器值 */
} Odometer_Calibration_t;

/* ========================================================================== */
/*                              函数声明                                       */
/* ========================================================================== */

/**
 * @brief  初始化里程计模块
 * @note   系统启动时调用一次
 */
void Odometer_Init(void);

/**
 * @brief  更新里程计数据
 * @note   在 SysTick 中断中调用，每 2ms 执行一次
 *         必须在 ABEncoder_UpdateSpeed() 之后调用
 */
void Odometer_Update(void);

/**
 * @brief  重置坐标系
 * @note   将当前位置设为坐标原点 (0, 0)
 *         当前航向设为 0 度
 *         累计里程清零
 *         通常在巡线模式启动时调用
 */
void Odometer_Reset(void);

/**
 * @brief  仅重置坐标，保留累计里程
 * @note   将当前位置设为坐标原点 (0, 0)
 *         当前航向设为 0 度
 *         累计里程不变
 */
void Odometer_ResetCoordinate(void);

/**
 * @brief  获取累计行驶距离
 * @return 累计行驶距离 (mm)
 */
float Odometer_GetLocation(void);

/**
 * @brief  获取当前 X 坐标
 * @return X 坐标 (mm)
 */
float Odometer_GetX(void);

/**
 * @brief  获取当前 Y 坐标
 * @return Y 坐标 (mm)
 */
float Odometer_GetY(void);

/**
 * @brief  获取当前航向角
 * @return 航向角 (度)，范围 -180 ~ 180
 */
float Odometer_GetTheta(void);

/**
 * @brief  获取完整的里程计数据
 * @param  data  输出数据结构指针
 */
void Odometer_GetData(Odometer_Data_t *data);

/* ========================================================================== */
/*                              校准相关函数                                   */
/* ========================================================================== */

/**
 * @brief  开始编码器校准
 * @note   调用此函数后，手动推动小车直线行驶一段已知距离
 */
void Odometer_StartCalibration(void);

/**
 * @brief  结束编码器校准并计算参数
 * @param  actual_distance_mm  实际行驶距离 (mm)
 * @return 计算得到的 pulse_per_mm 值，需要更新到 ODOM_ENCODER_PULSE_PER_MM
 */
float Odometer_EndCalibration(float actual_distance_mm);

/**
 * @brief  检查校准是否激活
 * @return 1=激活, 0=未激活
 */
uint8_t Odometer_IsCalibrating(void);

/**
 * @brief  获取校准过程中的累计脉冲数 (用于调试)
 * @return 校准开始后的平均脉冲数
 */
int32_t Odometer_GetCalibrationPulseCount(void);

/* ========================================================================== */
/*                              陀螺仪融合选项                                 */
/* ========================================================================== */

/**
 * @brief  启用/禁用陀螺仪航向融合
 * @param  enable  1=使用陀螺仪, 0=仅用编码器
 * @note   陀螺仪可以提高转向精度，但需要正确校准
 */
void Odometer_EnableGyroFusion(uint8_t enable);

/**
 * @brief  设置陀螺仪融合权重
 * @param  weight  陀螺仪权重 (0.0~1.0)，默认 0.9
 * @note   weight=1.0 完全信任陀螺仪，weight=0.0 完全信任编码器
 */
void Odometer_SetGyroFusionWeight(float weight);

#endif /* __ODOMETER_H */

#include "stm32f10x.h"
#include "OLED_Font.h"

/*引脚配置*/
#define OLED_W_SCL(x)		GPIO_WriteBit(GPIOB, GPIO_Pin_5, (BitAction)(x))
#define OLED_W_SDA(x)		GPIO_WriteBit(GPIOB, GPIO_Pin_4, (BitAction)(x))

/*引脚初始化*/
void OLED_I2C_Init(void)
{
	RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB | RCC_APB2Periph_AFIO, ENABLE);	//开启GPIOB的时钟
	GPIO_PinRemapConfig(GPIO_Remap_SWJ_JTAGDisable,ENABLE);
	//使用各个外设前必须开启时钟，否则对外设的操作无效

	GPIO_InitTypeDef GPIO_InitStructure;
 	GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_OD;
	GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
	GPIO_InitStructure.GPIO_Pin = GPIO_Pin_4;
 	GPIO_Init(GPIOB, &GPIO_InitStructure);
	GPIO_InitStructure.GPIO_Pin = GPIO_Pin_5;
 	GPIO_Init(GPIOB, &GPIO_InitStructure);

	OLED_W_SCL(1);
	OLED_W_SDA(1);
}

/**
  * @brief  I2C开始
  * @param  无
  * @retval 无
  */
void OLED_I2C_Start(void)
{
	OLED_W_SDA(1);
	OLED_W_SCL(1);
	OLED_W_SDA(0);
	OLED_W_SCL(0);
}

/**
  * @brief  I2C停止
  * @param  无
  * @retval 无
  */
void OLED_I2C_Stop(void)
{
	OLED_W_SDA(0);
	OLED_W_SCL(1);
	OLED_W_SDA(1);
}

/**
  * @brief  I2C发送一个字节
  * @param  Byte 要发送的一个字节
  * @retval 无
  */
void OLED_I2C_SendByte(uint8_t Byte)
{
	uint8_t i;
	for (i = 0; i < 8; i++)
	{
		OLED_W_SDA(!!(Byte & (0x80 >> i)));
		OLED_W_SCL(1);
		OLED_W_SCL(0);
	}
	OLED_W_SCL(1);	//额外的一个时钟，不处理应答信号
	OLED_W_SCL(0);
}

/**
  * @brief  OLED写命令
  * @param  Command 要写入的命令
  * @retval 无
  */
void OLED_WriteCommand(uint8_t Command)
{
	OLED_I2C_Start();
	OLED_I2C_SendByte(0x78);		//从机地址
	OLED_I2C_SendByte(0x00);		//写命令
	OLED_I2C_SendByte(Command); 
	OLED_I2C_Stop();
}

/**
  * @brief  OLED写数据
  * @param  Data 要写入的数据
  * @retval 无
  */
void OLED_WriteData(uint8_t Data)
{
	OLED_I2C_Start();
	OLED_I2C_SendByte(0x78);		//从机地址
	OLED_I2C_SendByte(0x40);		//写数据
	OLED_I2C_SendByte(Data);
	OLED_I2C_Stop();
}

/**
  * @brief  OLED设置光标位置
  * @param  Y 以左上角为原点，向下方向的坐标，范围：0~7
  * @param  X 以左上角为原点，向右方向的坐标，范围：0~127
  * @retval 无
  */
void OLED_SetCursor(uint8_t Y, uint8_t X)
{
	OLED_WriteCommand(0xB0 | Y);					//设置Y位置
	OLED_WriteCommand(0x10 | ((X & 0xF0) >> 4));	//设置X位置高4位
	OLED_WriteCommand(0x00 | (X & 0x0F));			//设置X位置低4位
}

/**
  * @brief  OLED清屏
  * @param  无
  * @retval 无
  */
void OLED_Clear(void)
{  
	uint8_t i, j;
	for (j = 0; j < 8; j++)
	{
		OLED_SetCursor(j, 0);
		for(i = 0; i < 128; i++)
		{
			OLED_WriteData(0x00);
		}
	}
}

/**
  * @brief  OLED显示一个字符
  * @param  Line 行位置，范围：1~4
  * @param  Column 列位置，范围：1~16
  * @param  Char 要显示的一个字符，范围：ASCII可见字符
  * @retval 无
  */
void OLED_ShowChar(uint8_t Line, uint8_t Column, char Char)
{      	
	uint8_t i;
	OLED_SetCursor((Line - 1) * 2, (Column - 1) * 8);		//设置光标位置在上半部分
	for (i = 0; i < 8; i++)
	{
		OLED_WriteData(OLED_F8x16[Char - ' '][i]);			//显示上半部分内容
	}
	OLED_SetCursor((Line - 1) * 2 + 1, (Column - 1) * 8);	//设置光标位置在下半部分
	for (i = 0; i < 8; i++)
	{
		OLED_WriteData(OLED_F8x16[Char - ' '][i + 8]);		//显示下半部分内容
	}
}

/**
  * @brief  OLED显示字符串
  * @param  Line 起始行位置，范围：1~4
  * @param  Column 起始列位置，范围：1~16
  * @param  String 要显示的字符串，范围：ASCII可见字符
  * @retval 无
  */
void OLED_ShowString(uint8_t Line, uint8_t Column, char *String)
{
	uint8_t i;
	for (i = 0; String[i] != '\0'; i++)
	{
		OLED_ShowChar(Line, Column + i, String[i]);
	}
}

/**
  * @brief  OLED次方函数
  * @retval 返回值等于X的Y次方
  */
uint32_t OLED_Pow(uint32_t X, uint32_t Y)
{
	uint32_t Result = 1;
	while (Y--)
	{
		Result *= X;
	}
	return Result;
}

/**
  * @brief  OLED显示数字（十进制，正数）
  * @param  Line 起始行位置，范围：1~4
  * @param  Column 起始列位置，范围：1~16
  * @param  Number 要显示的数字，范围：0~4294967295
  * @param  Length 要显示数字的长度，范围：1~10
  * @retval 无
  */
void OLED_ShowNum(uint8_t Line, uint8_t Column, uint32_t Number, uint8_t Length)
{
	uint8_t i;
	for (i = 0; i < Length; i++)							
	{
		OLED_ShowChar(Line, Column + i, Number / OLED_Pow(10, Length - i - 1) % 10 + '0');
	}
}

/**
  * @brief  OLED显示数字（十进制，带符号数）
  * @param  Line 起始行位置，范围：1~4
  * @param  Column 起始列位置，范围：1~16
  * @param  Number 要显示的数字，范围：-2147483648~2147483647
  * @param  Length 要显示数字的长度，范围：1~10
  * @retval 无
  */
void OLED_ShowSignedNum(uint8_t Line, uint8_t Column, int32_t Number, uint8_t Length)
{
	uint8_t i;
	uint32_t Number1;
	if (Number >= 0)
	{
		OLED_ShowChar(Line, Column, '+');
		Number1 = Number;
	}
	else
	{
		OLED_ShowChar(Line, Column, '-');
		Number1 = -Number;
	}
	for (i = 0; i < Length; i++)							
	{
		OLED_ShowChar(Line, Column + i + 1, Number1 / OLED_Pow(10, Length - i - 1) % 10 + '0');
	}
}

/**
  * @brief  OLED显示数字（十六进制，正数）
  * @param  Line 起始行位置，范围：1~4
  * @param  Column 起始列位置，范围：1~16
  * @param  Number 要显示的数字，范围：0~0xFFFFFFFF
  * @param  Length 要显示数字的长度，范围：1~8
  * @retval 无
  */
void OLED_ShowHexNum(uint8_t Line, uint8_t Column, uint32_t Number, uint8_t Length)
{
	uint8_t i, SingleNumber;
	for (i = 0; i < Length; i++)							
	{
		SingleNumber = Number / OLED_Pow(16, Length - i - 1) % 16;
		if (SingleNumber < 10)
		{
			OLED_ShowChar(Line, Column + i, SingleNumber + '0');
		}
		else
		{
			OLED_ShowChar(Line, Column + i, SingleNumber - 10 + 'A');
		}
	}
}

/**
  * @brief  OLED显示数字（二进制，正数）
  * @param  Line 起始行位置，范围：1~4
  * @param  Column 起始列位置，范围：1~16
  * @param  Number 要显示的数字，范围：0~1111 1111 1111 1111
  * @param  Length 要显示数字的长度，范围：1~16
  * @retval 无
  */
void OLED_ShowBinNum(uint8_t Line, uint8_t Column, uint32_t Number, uint8_t Length)
{
	uint8_t i;
	for (i = 0; i < Length; i++)							
	{
		OLED_ShowChar(Line, Column + i, Number / OLED_Pow(2, Length - i - 1) % 2 + '0');
	}
}

/**
  * @brief  OLED初始化
  * @param  无
  * @retval 无
  */
void OLED_Init(void)
{
	uint32_t i, j;

	for (i = 0; i < 1000; i++)			//上电延时
	{
		for (j = 0; j < 1000; j++);
	}

	OLED_I2C_Init();			//端口初始化

	OLED_WriteCommand(0xAE);	//关闭显示

	OLED_WriteCommand(0xD5);	//设置显示时钟分频比/振荡器频率
	OLED_WriteCommand(0x80);

	OLED_WriteCommand(0xA8);	//设置多路复用率
	OLED_WriteCommand(0x3F);

	OLED_WriteCommand(0xD3);	//设置显示偏移
	OLED_WriteCommand(0x00);

	OLED_WriteCommand(0x40);	//设置显示开始行

	OLED_WriteCommand(0xA1);	//设置左右方向，0xA1正常 0xA0左右反置

	OLED_WriteCommand(0xC8);	//设置上下方向，0xC8正常 0xC0上下反置

	OLED_WriteCommand(0xDA);	//设置COM引脚硬件配置
	OLED_WriteCommand(0x12);

	OLED_WriteCommand(0x81);	//设置对比度控制
	OLED_WriteCommand(0xCF);

	OLED_WriteCommand(0xD9);	//设置预充电周期
	OLED_WriteCommand(0xF1);

	OLED_WriteCommand(0xDB);	//设置VCOMH取消选择级别
	OLED_WriteCommand(0x30);

	OLED_WriteCommand(0xA4);	//设置整个显示打开/关闭

	OLED_WriteCommand(0xA6);	//设置正常/倒转显示

	OLED_WriteCommand(0x8D);	//设置充电泵
	OLED_WriteCommand(0x14);

	OLED_WriteCommand(0xAF);	//开启显示

	OLED_Clear();				//OLED清屏
}

